select s.region, case when s.sqft >= 17575 then 'high' when s.sqft >= 3177 then 'mid' else 'low' end as sqft_bucket, count(i.quantity) as quantity_count, count(distinct i.quantity) as unique_stores from inventory i join products p on i.product_id = p.id left outer join stores s on i.store_id = s.id where p.cost is null group by s.region, case when s.sqft >= 17575 then 'high' when s.sqft >= 3177 then 'mid' else 'low' end order by unique_stores desc, region, sqft_bucket limit 1;
